package com.arun.mymessages;
import android.content.*;import android.app.*;import android.os.*;import android.provider.Telephony;import android.telephony.SmsMessage;
public class SmsReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){if(!Telephony.Sms.Intents.SMS_DELIVER_ACTION.equals(i.getAction()))return;SmsMessage[] m=Telephony.Sms.Intents.getMessagesFromIntent(i);if(m==null)return;String from=m.length>0?m[0].getDisplayOriginatingAddress():"SMS";String body="";for(SmsMessage x:m)body+=x.getMessageBody();if(Build.VERSION.SDK_INT>=26)((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("sms","SMS",NotificationManager.IMPORTANCE_HIGH));Notification.Builder n=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"sms"):new Notification.Builder(c);n.setSmallIcon(android.R.drawable.sym_action_email).setContentTitle(from).setContentText(body).setAutoCancel(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%100000),n.build());}}
